  `hrm_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'https://hrm.smcmfg.com.vn',
  `login_endpoint` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'https://hrm.smcmfg.com.vn/login',
  `portal_endpoint` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'https://hrm.smcmfg.com.vn/TangCa/DuyetTangCaKeHoach',
  `plan_export_endpoint` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'https://hrm.smcmfg.com.vn/Portal/TangCa/ExportDuyetTangCaKeHoach',
  `actual_export_endpoint` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'https://hrm.smcmfg.com.vn/Portal/TangCa/ExportDuyetTangCaThucTe',
  `download_endpoint` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'https://hrm.smcmfg.com.vn/Download/ExcelDownload',
  `last_sync_time` datetime DEFAULT NULL COMMENT 'Thời gian đồng bộ thực tế (GMT+7)',
  `last_sync_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'never_run' COMMENT 'never_run, success, failed',
  `last_sync_message` text COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nhật ký đồng bộ gần nhất',
  `last_sync_stats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Thống kê inserted, updated, errors' CHECK (json_valid(`last_sync_stats`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

