CREATE TABLE `ot_yearly_accumulations` (
  `id` int(11) NOT NULL,
  `employee_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `year` int(11) NOT NULL,
  `total_hours_m1` decimal(6,2) DEFAULT 0.00,
  `total_hours_m2` decimal(6,2) DEFAULT 0.00,
  `total_hours_m3` decimal(6,2) DEFAULT 0.00,
  `total_hours_m4` decimal(6,2) DEFAULT 0.00,
  `total_hours_m5` decimal(6,2) DEFAULT 0.00,
  `total_hours_m6` decimal(6,2) DEFAULT 0.00,
  `total_hours_m7` decimal(6,2) DEFAULT 0.00,
  `total_hours_m8` decimal(6,2) DEFAULT 0.00,
  `total_hours_m9` decimal(6,2) DEFAULT 0.00,
  `total_hours_m10` decimal(6,2) DEFAULT 0.00,
  `total_hours_m11` decimal(6,2) DEFAULT 0.00,
  `total_hours_m12` decimal(6,2) DEFAULT 0.00,
  `total_hours_year` decimal(7,2) DEFAULT 0.00,
  `remaining_hours` decimal(7,2) GENERATED ALWAYS AS (greatest(0,200.00 - `total_hours_year`)) STORED,
  `usage_percent` decimal(5,2) GENERATED ALWAYS AS (least(999.99,`total_hours_year` / 200.00 * 100)) STORED,
  `warning_level` enum('green','yellow','red') COLLATE utf8mb4_unicode_ci DEFAULT 'green',
  `last_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

